<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if($id>0&&in_array($status,['approved','rejected','pending'],true)){$s=$pdo->prepare('UPDATE product_reviews SET status=? WHERE id=?');$s->execute([$status,$id]);$_SESSION['flash']='Review status updated.';}redirect('reviews.php');}
$reviews=$pdo->query("SELECT r.*,p.name product_name,u.full_name customer_name FROM product_reviews r JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.user_id ORDER BY FIELD(r.status,'pending','approved','rejected'),r.created_at DESC")->fetchAll();admin_page_start('Product reviews');?><div class="panel"><p class="text-secondary">Approve reviews before they appear publicly on product pages.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Customer</th><th>Rating</th><th>Review</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=e($r['customer_name'])?></td><td><?= (int)$r['rating']?>/5</td><td><?=e($r['title']??'')?> <div class="small text-secondary"><?=e($r['review'])?></div></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status" class="form-select form-select-sm"><option value="pending">Pending</option><option value="approved" <?=$r['status']==='approved'?'selected':''?>>Approve</option><option value="rejected" <?=$r['status']==='rejected'?'selected':''?>>Reject</option></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_page_end();?>
